32	#[inline]
33	fn is_at_query_feature_name(p: &mut CssParser) -> bool {
34	    if CssSyntaxFeatures::Scss.is_supported(p) {
35	        is_at_scss_interpolated_identifier(p)
36	    } else {
37	        is_at_identifier(p)
38	    }
39	}
